322			t.Fatal(err)
323		}
324		doc, _ := buildBundle(t, payload)
325		other := chunkCID([]byte("unreferenced"))
326	
327		cases := map[string]func(map[string]any){
328			"root cid mismatch": func(m map[string]any) {
329				m["root"].(map[string]any)["cid"] = chunkCID([]byte("wrong"))
330			},
331			"size mismatch": func(m map[string]any) {
332				m["root"].(map[string]any)["size"] = len(payload) - 1
333			},
334			"missing block": func(m map[string]any) {
335				m["blocks"] = m["blocks"].([]any)[:1]
336			},
337			"duplicate block": func(m map[string]any) {
338				blocks := m["blocks"].([]any)
339				m["blocks"] = append(blocks, blocks[0])
340			},
341			"unreferenced block": func(m map[string]any) {
342				m["blocks"] = append(m["blocks"].([]any), map[string]any{
343					"cid":  other,
344					"data": base64.StdEncoding.EncodeToString([]byte("unreferenced")),
345				})
346			},
347			"digest mismatch": func(m map[string]any) {
348				block := m["blocks"].([]any)[0].(map[string]any)
349				block["data"] = base64.StdEncoding.EncodeToString([]byte("tampered"))
350			},
351			"short middle chunk": func(m map[string]any) {
352				// Reference the 10-byte tail block as the first chunk.
353				chunks := m["root"].(map[string]any)["chunks"].([]any)
354				chunks[0], chunks[1] = chunks[1], chunks[0]
355			},
356			"empty object with chunks": func(m map[string]any) {
