1	package server
2	
3	import (
4		"bytes"
5		"encoding/base64"
6		"encoding/json"
7		"errors"
8		"io"
9		"mime"
10		"net/http"
11		"sort"
12		"strconv"
13	)
14	
15	// deltaBundleMediaType is the media type exchanged by the incremental
16	// bundle endpoints. The document shape is identical to a full bundle; only
17	// the block set and the reconstruction rules differ.
18	const deltaBundleMediaType = "application/vnd.cidvault.delta-bundle+json"
19	
20	// haveRequest is the JSON body of POST /v1/delta-bundles/{cid}: the block
21	// identifiers the receiver already holds.
22	type haveRequest struct {
23		Have *[]string `json:"have"`
24	}
25	
26	// postDeltaBundleByID handles POST /v1/delta-bundles/{cid}: export only the
27	// manifest-referenced blocks the receiver does not list in "have".
28	func (s *store) postDeltaBundleByID(w http.ResponseWriter, r *http.Request) {
29		if r.Method != http.MethodPost {
30			w.Header().Set("Allow", http.MethodPost)
31			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
32			return
33		}
34		cid := r.PathValue("cid")
35		if !validCID(cid) {
36			writeError(w, http.StatusBadRequest, "invalid_cid")
37			return
38		}
39		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
40		if err != nil || mediaType != "application/json" {
41			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
42			return
43		}
44		body, err := io.ReadAll(io.LimitReader(r.Body, maxBundleSize+1))
45		if err != nil || len(body) > maxBundleSize {
46			writeError(w, http.StatusBadRequest, "invalid_request")
47			return
48		}
49		have, ok := parseHaveRequest(body)
50		if !ok {
51			writeError(w, http.StatusBadRequest, "invalid_request")
52			return
53		}
54		obj := s.get(cid)
55		if obj == nil {
56			writeError(w, http.StatusNotFound, "object_not_found")
57			return
58		}
59	
60		// Map each unique referenced identifier to its raw bytes, then drop
61		// every identifier the receiver already holds.
62		dataByCID := make(map[string][]byte, len(obj.cids))
63		for i, c := range obj.cids {
64			dataByCID[c] = obj.chunks[i]
65		}
66		cids := make([]string, 0, len(dataByCID))
67		for c := range dataByCID {
68			if have[c] {
69				continue
70			}
71			cids = append(cids, c)
72		}
73		sort.Strings(cids)
74		blocks := make([]bundleBlock, 0, len(cids))
75		for _, c := range cids {
76			blocks = append(blocks, bundleBlock{
77				CID:  c,
78				Data: base64.StdEncoding.EncodeToString(dataByCID[c]),
79			})
80		}
81		w.Header().Set("Content-Type", deltaBundleMediaType)
82		_ = json.NewEncoder(w).Encode(bundleDocument{
83			Version: bundleVersion,
84			Root: bundleRoot{
85				CID:       obj.cid,
86				Size:      obj.size,
87				ChunkSize: ChunkSize,
88				Chunks:    obj.cids,
89			},
90			Blocks: blocks,
91		})
92	}
93	
94	// parseHaveRequest strictly decodes {"have":[...]}. Every entry must be a
95	// well-formed identifier and no identifier may repeat; entries unrelated to
96	// the exported object are tolerated by the caller, which simply skips them.
97	func parseHaveRequest(body []byte) (map[string]bool, bool) {
98		if !wellFormedJSON(body) {
99			return nil, false
100		}
101		var req haveRequest
102		dec := json.NewDecoder(bytes.NewReader(body))
103		dec.DisallowUnknownFields()
104		if err := dec.Decode(&req); err != nil || req.Have == nil {
105			return nil, false
106		}
107		have := make(map[string]bool, len(*req.Have))
108		for _, c := range *req.Have {
109			if !validCID(c) || have[c] {
110				return nil, false
111			}
112			have[c] = true
113		}
114		return have, true
115	}
116	
117	// postDeltaBundle handles POST /v1/delta-bundles: reconstruct an object from
118	// the bundled blocks combined with blocks the local store still references.
119	func (s *store) postDeltaBundle(w http.ResponseWriter, r *http.Request) {
120		if r.Method != http.MethodPost {
121			w.Header().Set("Allow", http.MethodPost)
122			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
123			return
124		}
125		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
126		if err != nil || mediaType != deltaBundleMediaType {
127			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
128			return
129		}
130		body, err := io.ReadAll(io.LimitReader(r.Body, maxBundleSize+1))
131		if err != nil {
132			writeError(w, http.StatusBadRequest, "invalid_delta_bundle")
133			return
134		}
135		if len(body) > maxBundleSize {
136			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
137			return
138		}
139		content, code, status := parseDeltaBundle(body)
140		if code != "" {
141			writeError(w, status, code)
142			return
143		}
144		obj, code, status := s.assembleDelta(content)
145		if code != "" {
146			writeError(w, status, code)
147			return
148		}
149		stored, created := s.put(obj)
150		respStatus := http.StatusOK
151		if created {
152			respStatus = http.StatusCreated
153		}
154		writeJSON(w, respStatus, objectResponse{
155			CID:       stored.cid,
156			Size:      stored.size,
157			ChunkSize: ChunkSize,
158			Chunks:    stored.cids,
159			Created:   created,
160		})
161	}
162	
163	// deltaContent is the validated result of parsing an incremental bundle:
164	// the manifest claims and the raw bytes of every block carried inline. Blocks
165	// referenced but not carried must be supplied from the local store.
166	type deltaContent struct {
167		cid    string
168		size   int
169		cids   []string
170		blocks map[string][]byte
171	}
172	
173	// parseDeltaBundle fully validates everything checkable without touching the
174	// store. On failure it returns the error code and HTTP status; the store is
175	// never touched on the failure path.
176	func parseDeltaBundle(body []byte) (*deltaContent, string, int) {
177		invalid := func() (*deltaContent, string, int) {
178			return nil, "invalid_delta_bundle", http.StatusBadRequest
179		}
180		integrity := func() (*deltaContent, string, int) {
181			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
182		}
183	
184		if !wellFormedJSON(body) {
185			return invalid()
186		}
187		var doc bundleJSON
188		dec := json.NewDecoder(bytes.NewReader(body))
189		dec.DisallowUnknownFields()
190		if err := dec.Decode(&doc); err != nil {
191			return invalid()
192		}
193		if doc.Version == nil || doc.Root == nil || doc.Blocks == nil ||
194			doc.Root.CID == nil || doc.Root.Size == nil || doc.Root.ChunkSize == nil ||
195			doc.Root.Chunks == nil {
196			return invalid()
197		}
198		for _, b := range *doc.Blocks {
199			if b.CID == nil || b.Data == nil {
200				return invalid()
201			}
202		}
203	
204		// Same integer parsing policy as full bundles: an out-of-range version
205		// or chunk size is an unsupported value, an out-of-range size is too
206		// large, and anything non-integral is a malformed document.
207		version, err := parseInt(*doc.Version)
208		if err != nil {
209			if errors.Is(err, strconv.ErrRange) {
210				return nil, "unsupported_delta_bundle", http.StatusUnprocessableEntity
211			}
212			return invalid()
213		}
214		chunkSize, err := parseInt(*doc.Root.ChunkSize)
215		if err != nil {
216			if errors.Is(err, strconv.ErrRange) {
217				return nil, "unsupported_delta_bundle", http.StatusUnprocessableEntity
218			}
219			return invalid()
220		}
221		size, err := parseInt(*doc.Root.Size)
222		if err != nil {
223			if errors.Is(err, strconv.ErrRange) {
224				return nil, "payload_too_large", http.StatusRequestEntityTooLarge
225			}
226			return invalid()
227		}
228	
229		if !validCID(*doc.Root.CID) {
230			return invalid()
231		}
232		for _, c := range *doc.Root.Chunks {
233			if !validCID(c) {
234				return invalid()
235			}
236		}
237		blockData := make(map[string][]byte, len(*doc.Blocks))
238		for _, b := range *doc.Blocks {
239			if !validCID(*b.CID) {
240				return invalid()
241			}
242			data, err := base64.StdEncoding.DecodeString(*b.Data)
243			if err != nil {
244				return invalid()
245			}
246			blockData[*b.CID] = data
247		}
248	
249		if version != bundleVersion || chunkSize != ChunkSize {
250			return nil, "unsupported_delta_bundle", http.StatusUnprocessableEntity
251		}
252		if size > MaxObjectSize {
253			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
254		}
255		if size < 0 {
256			return integrity()
257		}
258	
259		// Carried blocks must be a subset of the unique referenced identifiers:
260		// no duplicates and nothing the manifest does not reference. Missing
261		// blocks are expected in an incremental bundle and come from the store.
262		referenced := make(map[string]bool, len(*doc.Root.Chunks))
263		for _, c := range *doc.Root.Chunks {
264			referenced[c] = true
265		}
266		seen := make(map[string]bool, len(*doc.Blocks))
267		for _, b := range *doc.Blocks {
268			if seen[*b.CID] || !referenced[*b.CID] {
269				return integrity()
270			}
271			seen[*b.CID] = true
272		}
273	
274		// Every carried block identifier must be the digest of its decoded bytes.
275		for cid, data := range blockData {
276			if chunkCID(data) != cid {
277				return integrity()
278			}
279		}
280	
281		cids := *doc.Root.Chunks
282		if (size == 0) != (len(cids) == 0) {
283			return integrity()
284		}
285		return &deltaContent{
286			cid:    *doc.Root.CID,
287			size:   size,
288			cids:   append([]string{}, cids...),
289			blocks: blockData,
290		}, "", 0
291	}
292	
293	// assembleDelta merges the carried blocks with blocks still referenced by
294	// local objects, then applies the same fixed chunking, length and root
295	// checks as a full-bundle import. A referenced block held nowhere yields
296	// missing_block. The store itself is not mutated here; put happens only once
297	// the returned object is fully validated.
298	func (s *store) assembleDelta(content *deltaContent) (*object, string, int) {
299		chunks := make([][]byte, len(content.cids))
300		for i, c := range content.cids {
301			if data, ok := content.blocks[c]; ok {
302				chunks[i] = data
303				continue
304			}
305			data := s.getBlock(c)
306			if data == nil {
307				return nil, "missing_block", http.StatusUnprocessableEntity
308			}
309			chunks[i] = data
310		}
311	
312		total := 0
313		for i, data := range chunks {
314			n := len(data)
315			if i < len(chunks)-1 {
316				if n != ChunkSize {
317					return nil, "integrity_check_failed", http.StatusUnprocessableEntity
318				}
319			} else if n < 1 || n > ChunkSize {
320				return nil, "integrity_check_failed", http.StatusUnprocessableEntity
321			}
322			total += n
323		}
324		if total > MaxObjectSize {
325			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
326		}
327		if total != content.size {
328			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
329		}
330		if rootCID(content.size, content.cids) != content.cid {
331			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
332		}
333		return &object{
334			cid:    content.cid,
335			size:   content.size,
336			chunks: chunks,
337			cids:   content.cids,
338		}, "", 0
339	}
340

